1	package cli
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"os"
8		"reflect"
9		"regexp"
10		"strings"
11		"time"
12	
13		"github.com/spf13/cobra"
14	)
15	
16	type Options struct {
17		Version string
18		Env     EntireEnv
19		Runner  CommandRunner
20		Now     func() time.Time
21	}
22	
23	// Execute runs the plugin root command with the real process environment.
24	func Execute(version string) error {
25		cmd := NewRootCommand(Options{
26			Version: version,
27			Env:     EnvFromOS(),
28		})
29		err := cmd.Execute()
30		if err != nil && commandErrorWasRendered(err) {
31			return err
32		}
33		return err
34	}
35	
36	func NewRootCommand(opts Options) *cobra.Command {
37		if opts.Version == "" {
38			opts.Version = "dev"
39		}
40		if opts.Runner == nil {
41			opts.Runner = ExecRunner{}
42		}
43		if opts.Now == nil {
44			opts.Now = time.Now
45		}
46	
47		cmd := &cobra.Command{
48			Use:           "entire-brain",
49			Short:         "Export Entire session history for agent review",
50			SilenceUsage:  true,
51			SilenceErrors: true,
52			Long: `entire-brain is an external-command plugin for the Entire CLI.
53	
54	It exports checkpointed session transcripts and metadata into a directory an
55	agent can inspect to understand project history.`,
56			RunE: func(cmd *cobra.Command, args []string) error {
57				return cmd.Help()
58			},
59		}
60	
61		cmd.AddCommand(newDoctorCommand(opts))
62		cmd.AddCommand(newAgentStatusCommand(opts))
63		cmd.AddCommand(newBrainBriefCommand(opts))
64		cmd.AddCommand(newConfigCommand(opts.Env))
65		cmd.AddCommand(newExportCommand(opts))
66		cmd.AddCommand(newBrainGuideCommand())
67		cmd.AddCommand(newHistoryIndexCommand(opts))
68		cmd.AddCommand(newBrainInspectCommand(opts))
69		cmd.AddCommand(newMCPCommand(opts))
70		cmd.AddCommand(newSemanticBundleCommand(opts))
71		cmd.AddCommand(newSemanticChangesCommand(opts))
72		cmd.AddCommand(newSemanticContextCommand(opts))
73		cmd.AddCommand(newSemanticGCCommand(opts))
74		cmd.AddCommand(newSemanticImpactCommand(opts))
75		cmd.AddCommand(newSemanticIndexCommand(opts))
76		cmd.AddCommand(newSemanticQueryCommand(opts))
77		cmd.AddCommand(newSemanticRoutesCommand(opts))
78		cmd.AddCommand(newPathCommand(opts))
79		cmd.AddCommand(newRefreshCommand(opts))
80		cmd.AddCommand(newSemanticRepairCommand(opts))
81		cmd.AddCommand(newSemanticResetCommand(opts))
82		cmd.AddCommand(newBrainSearchCommand(opts))
83		cmd.AddCommand(newSeedCommand(opts))
84		cmd.AddCommand(newBrainShowCommand(opts))
85		cmd.AddCommand(newSemanticStaleCommand(opts))
86		cmd.AddCommand(newSemanticTestsCommand(opts))
87		cmd.AddCommand(newSemanticToolsCommand(opts))
88		cmd.AddCommand(newSemanticWorkflowsCommand(opts))
89		cmd.AddCommand(newWorkspaceCommand(opts))
90		cmd.AddCommand(newVersionCommand(opts.Version))
91		wrapJSONErrorRendering(cmd)
92		return cmd
93	}
94	
95	type commandJSONError struct {
96		Code    string `json:"code"`
97		Message string `json:"message"`
98	}
99	
100	type renderedCommandError struct {
101		err error
102	}
103	
104	var errRenderedCommand = renderedCommandError{}
105	
106	func RenderedError() error {
107		return errRenderedCommand
108	}
109	
110	func (e renderedCommandError) Error() string {
111		if e.err == nil {
112			return "command error rendered"
113		}
114		return e.err.Error()
115	}
116	
117	func (e renderedCommandError) Unwrap() error {
118		return e.err
119	}
120	
121	func (e renderedCommandError) Is(target error) bool {
122		_, ok := target.(renderedCommandError)
123		return ok
124	}
125	
126	func commandErrorWasRendered(err error) bool {
127		_, ok := err.(renderedCommandError)
128		return ok
129	}
130	
131	func wrapJSONErrorRendering(cmd *cobra.Command) {
132		if cmd.Args != nil {
133			argsFunc := cmd.Args
134			cmd.Args = func(cmd *cobra.Command, args []string) error {
135				err := argsFunc(cmd, args)
136				if err == nil || !commandWantsJSONError(cmd) {
137					return err
138				}
139				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
140				return renderedCommandError{err: err}
141			}
142		}
143		if cmd.RunE != nil {
144			run := cmd.RunE
145			cmd.RunE = func(cmd *cobra.Command, args []string) error {
146				err := run(cmd, args)
147				if err == nil || !commandWantsJSONError(cmd) {
148					return err
149				}
150				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
151				return renderedCommandError{err: err}
152			}
153		}
154		cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
155			if !commandWantsJSONError(cmd) {
156				return err
157			}
158			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
159			return renderedCommandError{err: err}
160		})
161		for _, child := range cmd.Commands() {
162			wrapJSONErrorRendering(child)
163		}
164	}
165	
166	func commandWantsJSONError(cmd *cobra.Command) bool {
167		if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
168			return commandJSONFlagEnabled(flag.Value.String())
169		}
170		if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
171			return commandJSONFlagEnabled(flag.Value.String())
172		}
173		for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
174			if arg == "--json" {
175				return true
176			}
177			if strings.HasPrefix(arg, "--json=") {
178				value := strings.TrimPrefix(arg, "--json=")
179				return value == "" || value == "true" || value == "1"
180			}
181		}
182		return false
183	}
184	
185	func commandJSONFlagEnabled(value string) bool {
186		value = strings.ToLower(value)
187		return value != "false" && value != "0"
188	}
189	
190	func commandRawArgs(cmd *cobra.Command) []string {
191		root := cmd.Root()
192		if root == nil {
193			return os.Args[1:]
194		}
195		value := reflect.ValueOf(root)
196		if value.Kind() != reflect.Pointer || value.IsNil() {
197			return os.Args[1:]
198		}
199		args := value.Elem().FieldByName("args")
200		if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
201			return os.Args[1:]
202		}
203		out := make([]string, 0, args.Len())
204		for i := 0; i < args.Len(); i++ {
205			out = append(out, args.Index(i).String())
206		}
207		return out
208	}
209	
210	var commandErrorCodePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)
211	
212	func writeCommandJSONError(w io.Writer, err error) error {
213		envelope := commandJSONError{
214			Code:    commandErrorCode(err),
215			Message: err.Error(),
216		}
217		data, marshalErr := json.MarshalIndent(envelope, "", "  ")
218		if marshalErr != nil {
219			return marshalErr
220		}
221		_, writeErr := fmt.Fprintln(w, string(data))
222		return writeErr
223	}
224	
225	func commandErrorCode(err error) string {
226		message := err.Error()
227		code, _, ok := strings.Cut(message, ":")
228		if ok {
229			code = strings.TrimSpace(code)
230			if commandErrorCodePattern.MatchString(code) {
231				return code
232			}
233		}
234		return "command_failed"
235	}
